<script setup lang="ts">
/**
 * A changed value or text, shown as old and new (`design/components/diff.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/diff.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onMounted, ref, useId, watch } from 'vue'

import { devWarning, diffLines, diffRuns } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/diff.module.css'
import Button from '../controls/Button.vue'

export interface DiffMessages {
  /** Read before the old value of a value that changed: "from". */
  from: string
  /** Read between the old value and the new one: "to". */
  to: string
  /** Read before a value, or a line, that only the new side has. */
  added: string
  /** Read before a value, or a line, that only the old side has. */
  removed: string
  /** A collapsed run's Button. */
  unchanged: (count: number) => string
}

export interface DiffProps {
  /**
   * The new value. Missing, `null` or empty means there is none: with a `before`, the change is
   * a removal. Equal sides are no change.
   */
  after?: string | null
  /**
   * The old value. Missing, `null` or empty means there was none: with an `after`, the change is
   * an addition.
   */
  before?: string | null
  /**
   * In `lines`, the unchanged lines kept beside each change. The unchanged lines past them are
   * one row that says how many it holds and shows them when pressed. `Infinity` keeps every
   * line.
   */
  context?: number
  /**
   * `inline` (the default) is a short value inside a sentence or a cell. `lines` compares two
   * texts of several lines, line by line.
   */
  display?: 'inline' | 'lines'
  /**
   * Names the `lines` form, which is a region. The `lines` form needs it; `inline` does not use
   * it.
   */
  label?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: DiffMessages
}

defineOptions({ name: 'Diff', inheritAttrs: false })

const props = withDefaults(defineProps<DiffProps>(), {
  context: 3,
  display: 'inline',
  messages: () => ({
    from: 'from',
    to: 'to',
    added: 'added',
    removed: 'removed',
    unchanged: (count: number) => `${count} unchanged ${count === 1 ? 'line' : 'lines'}`,
  }),
})
const uid = useId()
const opened = ref([] as number[])
const old = computed(() => props.before ?? '')
const next = computed(() => props.after ?? '')
const runs = computed(() =>
  props.display === 'lines' ? diffRuns(diffLines(old.value, next.value), props.context) : [],
)
const effect1 = () => {
  devWarning(
    props.display === 'lines' && props.label === undefined,
    'Diff: the `lines` form is a region, and a region needs a name; pass `label`.',
  )
}
onMounted(effect1)
watch(() => props.display === 'lines' && props.label === undefined, effect1, { flush: 'post' })
</script>

<template>
  <template v-if="old !== '' || next !== ''">
    <section
      v-if="display === 'lines'"
      :class="styles.lines"
      :aria-label="label"
      data-member="diff"
    >
      <!-- rows -->
      <ol :class="styles.rows" role="list">
        <template v-for="piece in runs" :key="piece.key">
          <!-- run -->
          <li v-if="piece.collapsed" :class="styles.run">
            <div :class="styles.fold">
              <Button
                variant="ghost"
                tone="neutral"
                size="sm"
                :icon="opened.includes(piece.key) ? 'collapse' : 'expand'"
                :label="messages.unchanged(piece.rows.length)"
                :expanded="opened.includes(piece.key)"
                :aria-controls="opened.includes(piece.key) ? `${uid}-run-${piece.key}` : undefined"
                @click="
                  opened = opened.includes(piece.key)
                    ? opened.filter((key) => key !== piece.key)
                    : [...opened, piece.key]
                "
              />
            </div>
            <!-- lines -->
            <ol
              v-if="opened.includes(piece.key)"
              :class="styles.rows"
              :id="`${uid}-run-${piece.key}`"
              role="list"
            >
              <template
                v-for="row in piece.rows"
                :key="
                  row.kind === 'removed'
                    ? `r${row.beforeLine}`
                    : `${row.kind === 'added' ? 'a' : 's'}${row.afterLine}`
                "
              >
                <!-- row -->
                <li :class="styles.row" :data-kind="row.kind === 'same' ? undefined : row.kind">
                  <!-- marker -->
                  <span :class="styles.marker" aria-hidden="true">
                    {{ row.kind === 'added' ? '+' : row.kind === 'removed' ? '−' : '' }}
                  </span>
                  <span v-if="row.kind !== 'same'" :class="styles.spoken">
                    {{ (row.kind === 'added' ? messages.added : messages.removed) + ' ' }}
                  </span>
                  <!-- text -->
                  <span :class="styles.text">
                    {{ row.text }}
                  </span>
                </li>
              </template>
            </ol>
          </li>
          <template v-else>
            <template
              v-for="row in piece.rows"
              :key="
                row.kind === 'removed'
                  ? `r${row.beforeLine}`
                  : `${row.kind === 'added' ? 'a' : 's'}${row.afterLine}`
              "
            >
              <!-- row -->
              <li :class="styles.row" :data-kind="row.kind === 'same' ? undefined : row.kind">
                <!-- marker -->
                <span :class="styles.marker" aria-hidden="true">
                  {{ row.kind === 'added' ? '+' : row.kind === 'removed' ? '−' : '' }}
                </span>
                <span v-if="row.kind !== 'same'" :class="styles.spoken">
                  {{ (row.kind === 'added' ? messages.added : messages.removed) + ' ' }}
                </span>
                <!-- text -->
                <span :class="styles.text">
                  {{ row.text }}
                </span>
              </li>
            </template>
          </template>
        </template>
      </ol>
    </section>
    <span v-else-if="old === next" :class="styles.inline" data-member="diff">
      {{ next }}
    </span>
    <span v-else-if="old === ''" :class="styles.inline" data-member="diff">
      <span :class="styles.spoken">
        {{ messages.added + ' ' }}
      </span>
      <!-- sign -->
      <span :class="styles.sign" aria-hidden="true">
        {{ '+' }}
      </span>
      <!-- after -->
      <ins :class="styles.after">
        {{ next }}
      </ins>
    </span>
    <span v-else-if="next === ''" :class="styles.inline" data-member="diff">
      <span :class="styles.spoken">
        {{ messages.removed + ' ' }}
      </span>
      <!-- before -->
      <del :class="styles.before">
        {{ old }}
      </del>
    </span>
    <span v-else :class="styles.inline" data-member="diff">
      <span :class="styles.spoken">
        {{ messages.from + ' ' }}
      </span>
      <!-- before -->
      <del :class="styles.before">
        {{ old }}
      </del>
      <!-- arrow -->
      <span :class="styles.arrow" aria-hidden="true">
        {{ '→' }}
      </span>
      <span :class="styles.spoken">
        {{ ' ' + messages.to + ' ' }}
      </span>
      <!-- after -->
      <ins :class="styles.after">
        {{ next }}
      </ins>
    </span>
  </template>
</template>
